query StratzGetPlayer ($steamAccountId: Long!) {
	player(steamAccountId: $steamAccountId) {
		... PlayerFields
	}
}
fragment PlayerFields on PlayerType {
	steamAccountId
	steamAccount {
		id
		name
		avatar
	}
	identity {
		name
	}
	matchCount
	winCount
	lastMatchDate
	ranks {
		rank
		leaderboardRank
	}
}

query StratzGetPlayers ($steamAccountIds: [Long!]!) {
