query StratzListPlayerMatches ($steamAccountId: Long!, $request: PlayerMatchesRequestType!) {
	player(steamAccountId: $steamAccountId) {
		steamAccountId
		matches(request: $request) {
			... MatchSummaryFields
		}
	}
}
fragment MatchSummaryFields on MatchType {
	id
